#
# The tensor product of two quantum states is defined as follows:
#
# $$
# \begin{equation}
# |\psi\rangle = \begin{bmatrix}
# \psi_0 \\
# \psi_1 \\
# \vdots \\
# \psi_{n-1}
# \end{bmatrix},
# \qquad
# |\phi\rangle = \begin{bmatrix}
# \phi_0 \\
# \phi_1 \\
# \vdots \\
# \phi_{m-1}
# \end{bmatrix}
# \end{equation}
# $$
#
# $$
# \begin{equation}
# |\psi\rangle \otimes |\phi\rangle = 
# \begin{bmatrix}
# \psi_0 \\
# \psi_1 \\
# \vdots \\
# \psi_{n-1}
# \end{bmatrix}
# \otimes
# \begin{bmatrix}
# \phi_0 \\
# \phi_1 \\
# \vdots \\
# \phi_{m-1}
# \end{bmatrix}
